from pathlib import Path
import json
base=Path(__file__).resolve().parents[1]
results=json.loads((base/'Data/verified_results.json').read_text())
selected=results['chosen_three_vertex_motifs']
html=r'''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dynamic Barycentric Observers — Interactive Lab</title>
<style>
:root{font-family:Inter,system-ui,-apple-system,Segoe UI,Arial,sans-serif;color:#172d42;background:#f2f6f7}*{box-sizing:border-box}body{margin:0;padding:24px}main{max-width:1100px;margin:0 auto}header{background:#153c49;color:white;border-radius:18px;padding:26px 32px}header h1{margin:4px 0 6px;font-size:28px}header p{margin:0;color:#d2e3e5;line-height:1.5}.eyebrow{letter-spacing:1.7px;text-transform:uppercase;font-size:11px;font-weight:800;color:#8dddd0}.layout{display:grid;grid-template-columns:1.15fr .85fr;gap:18px;margin-top:18px}.panel{background:white;border:1px solid #dae4e6;border-radius:15px;padding:22px;box-shadow:0 4px 16px #1d36400a}.panel h2{margin:0 0 14px;font-size:17px}.row{display:flex;gap:8px;flex-wrap:wrap;margin:11px 0}button,select{font:inherit;border:1px solid #becbd1;border-radius:8px;background:white;color:#174450;padding:8px 12px;cursor:pointer;font-size:13px}button.primary{background:#0d766e;color:#fff;border-color:#0d766e;font-weight:700}button:hover{filter:brightness(.96)}button:disabled{opacity:.45;cursor:default}#graph{width:100%;background:#f9fbfb;border:1px solid #e4ecee;border-radius:12px;min-height:320px}svg text{font-family:inherit}.statrow{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:12px 0}.stat{border-radius:10px;background:#eef4f5;padding:11px}.stat b{display:block;font-size:24px;color:#0b7068}.stat span{font-size:11px;color:#486070}.code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;background:#edf2f5;border-radius:8px;padding:10px;overflow-wrap:anywhere;font-size:12px}.tiny{color:#617887;font-size:12px;line-height:1.5}.divider{border-top:1px solid #e0e6e8;margin:16px 0}.checkboxes{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.checkboxes label{font-size:12px;background:#f5f8f9;border-radius:7px;padding:7px}.tag{display:inline-block;background:#e0f4ed;color:#08765f;padding:5px 9px;border-radius:999px;font-size:12px;font-weight:700}#history{max-height:300px;overflow:auto}.histrow{display:flex;justify-content:space-between;font-size:12px;border-bottom:1px solid #e9eef0;padding:7px 0}.footer{font-size:12px;color:#5f7481;line-height:1.5;padding:12px 4px}@media(max-width:800px){.layout{grid-template-columns:1fr}body{padding:10px}.statrow{grid-template-columns:repeat(2,1fr)}}
</style></head><body><main><header><div class="eyebrow">Wolfram Language research prototype · Exact finite models</div><h1>Dynamic Barycentric Observers</h1><p>Explore interacting graph and ternary-hypergraph updates, changing automorphism groups, and the exact reduced dynamics of symmetry-invariant observables. All calculations below run locally in your browser.</p></header>
<div class="layout"><section class="panel"><h2>Microscopic rewrite simulator</h2><div class="row"><select id="model"><option value="2">Pairwise graph rewriting</option><option value="3">Ternary hypergraph rewriting</option></select><button id="sample" class="primary">Load demonstrated example</button><button id="reset">Reset</button></div><div class="row"><label class="tiny"><input type="checkbox" id="complement"> Compose graph step with edge complementation (C∘F)</label></div><svg id="graph" viewBox="0 0 440 345" aria-label="Four vertex colored graph"></svg><div class="row"><button id="prev">← Back</button><button class="primary" id="next">Next rewrite →</button><button id="play">Play</button><button id="stop">Stop</button></div><div class="divider"></div><h2>Edit the current state</h2><p class="tiny">Toggle a spin or a graph edge, then advance one simultaneous rewrite step. For a ternary hypergraph, the four checkboxes represent its three-vertex hyperedges.</p><div id="colors" class="checkboxes"></div><div id="edges" class="checkboxes"></div></section>
<section class="panel"><h2>Symmetry and observer measurements</h2><span class="tag" id="status">Exact calculations</span><div class="statrow"><div class="stat"><b id="stepn">0</b><span>Time step</span></div><div class="stat"><b id="autg">–</b><span>Structure automorphisms</span></div><div class="stat"><b id="autc">–</b><span>Decorated automorphisms</span></div><div class="stat"><b id="edgesn">–</b><span>Present hyperedges</span></div><div class="stat"><b id="onesn">–</b><span>Active spins</span></div><div class="stat"><b id="obsn">–</b><span>Observer dimensions</span></div></div>
<h2>Symmetry-invariant observable</h2><p class="tiny" id="observertext"></p><div class="code" id="fingerprint"></div><div class="divider"></div><h2>History</h2><div id="history"></div><div class="divider"></div><h2>Exhaustive certification</h2><p class="tiny">Binary 4-vertex graphs: 1,024 labeled states → 90 colored graph orbits. Eight motif counts of size ≤2 give 66 observed states but fail exactness in 15 observer blocks. Adding five selected size-3 motif counts gives 86 states and exact dynamics; none of the candidate subsets of four or fewer size-3 motifs is exact.</p><p class="tiny">Ternary 4-vertex hypergraphs: 256 labeled states → 35 colored hypergraph orbits. All colored induced motifs of size ≤3 distinguish those 35 orbits exactly.</p></section></div>
<div class="panel" style="margin-top:18px"><h2>Multiway branch demonstration: single-edge deletion from a four-cycle</h2><p class="tiny">A symmetric four-cycle admits four distinct labeled edge-deletion events. The full D4 group (order 8) acts transitively on those four events. Each outcome is a path P4, whose graph automorphism group has order 2. This is a groupoid span of rewrite events, not a canonical homomorphism from D4 to the automorphism group of a chosen branch.</p><div class="row"><button id="cycle">Load symmetric C4</button><button id="delete0">Delete edge 1–2</button><button id="delete1">Delete edge 2–3</button><button id="delete2">Delete edge 3–4</button><button id="delete3">Delete edge 1–4</button></div></div>
<div class="footer">Scientific status: independent finite calculations and exhaustive Python verification. This browser viewer is a companion demonstration, not a native Wolfram Engine validation. The project archive contains the Wolfram Language implementation, tests, source and proofs.</div></main>
<script>
const PAIRS=[[0,1],[0,2],[0,3],[1,2],[1,3],[2,3]],TRIPLES=[[0,1,2],[0,1,3],[0,2,3],[1,2,3]];
const SELECTED=__MOTIFS__; const Q2CATALOG=__Q2CATALOG__;
function permutations(a){if(a.length===0)return [[]];return a.flatMap((x,i)=>permutations(a.filter((_,j)=>i!==j)).map(z=>[x,...z]));}
const PERMS=permutations([0,1,2,3]);
const initial=(a)=>a===2?{a,e:[1,1,1,0,0,0],s:[0,1,0,0]}:{a,e:[1,0,0,0],s:[1,1,0,1]};
let history=[],index=0,timer=null;
function faces(a){return a===2?PAIRS:TRIPLES};
function key(h){return h.join('-')};
function eq(x,y){return JSON.stringify(x)===JSON.stringify(y)};
function permute(st,p){const f=faces(st.a),d=Object.fromEntries(f.map((h,i)=>[key(h),st.e[i]]));const inv=new Array(4);p.forEach((v,i)=>inv[v]=i);
return {a:st.a,e:f.map(h=>d[key(h.map(i=>inv[i]).sort((a,b)=>a-b))]),s:inv.map(i=>st.s[i])};}
function autos(st,decorated){const base=decorated?st:{...st,s:[0,0,0,0]};return PERMS.filter(p=>eq(permute(base,p),base)).length}
function step(st){const s=st.s,e=st.e,f=faces(st.a);let ne=[],ns=[];
 if(st.a===2){ne=f.map((h,i)=>e[i]^(s[h[0]]^s[h[1]]));for(let i=0;i<4;i++){let z=s[i];f.forEach((h,k)=>{if(e[k] && h.includes(i))z^=s[h.find(v=>v!==i)]});ns.push(z)} }
 else{ne=f.map((h,i)=>e[i]^(h.reduce((v,j)=>v^s[j],0)));for(let i=0;i<4;i++){let z=s[i];f.forEach((h,k)=>{if(e[k] && h.includes(i))z^=h.filter(j=>j!==i).reduce((u,j)=>u&s[j],1)});ns.push(z)} }
 if(st.a===2 && document.getElementById('complement').checked)ne=ne.map(z=>1-z);
 return {a:st.a,e:ne,s:ns};}
function motifKey(st,subset){const f=faces(st.a),m=Object.fromEntries(f.map((x,i)=>[key(x),st.e[i]])),n=subset.length;
 const types=permutations(Array.from({length:n},(_,i)=>i)).map(p=>{let ord=p.map(i=>subset[i]);const colors=ord.map(i=>st.s[i]);let e=[];function subs(arr,k,start=0,pre=[]){if(pre.length===k){e.push(m[key(pre.slice().sort((a,b)=>a-b))]??0);return}for(let i=start;i<arr.length;i++)subs(arr,k,i+1,[...pre,arr[i]])}if(n>=st.a)subs(ord,st.a);return {colors,e};});
 types.sort((a,b)=>JSON.stringify(a.colors).localeCompare(JSON.stringify(b.colors))||JSON.stringify(a.e).localeCompare(JSON.stringify(b.e)));return types[0];}
function combinations(arr,k){if(k===0)return [[]];if(arr.length<k)return [];return arr.flatMap((x,i)=>combinations(arr.slice(i+1),k-1).map(rest=>[x,...rest]));}
function census(st,size){const bins=new Map;for(let j=1;j<=size;j++)for(let subset of combinations([0,1,2,3],j)){const m=motifKey(st,subset),label=JSON.stringify([j,m]);bins.set(label,(bins.get(label)||0)+1)}return bins;}
function selectedFeatures(st){const cnt=census(st,3);const selected=SELECTED.map(x=>cnt.get(JSON.stringify([3,x]))||0);return selected;}
function show(){const st=history[index],f=faces(st.a);document.getElementById('stepn').textContent=index;
 document.getElementById('autg').textContent=autos(st,false);document.getElementById('autc').textContent=autos(st,true);
 document.getElementById('edgesn').textContent=st.e.reduce((a,b)=>a+b,0);document.getElementById('onesn').textContent=st.s.reduce((a,b)=>a+b,0);
 const c=census(st,st.a===2?2:3),selected=selectedFeatures(st);document.getElementById('obsn').textContent=13;document.getElementById('complement').disabled=st.a===3;
 document.getElementById('observertext').textContent=st.a===2?'Selected observer: 8 counts of colored induced 1- and 2-vertex motifs plus 5 selected three-vertex motif counts.':'Ternary observer: complete census of colored induced 1-, 2-, and 3-vertex hypergraphs.';
 document.getElementById('fingerprint').textContent=st.a===2?`Q₂ = [${Q2CATALOG.map(x=>c.get(JSON.stringify(x))||0).join(', ')}]; 5 extra moments = [${selected.join(', ')}]`:`Hypergraph motif census: ${[...c.values()].join(', ')}`;
 const svg=document.getElementById('graph');svg.innerHTML='';const P=[[220,53],[356,169],[220,281],[84,169]];
 function elt(name,attrs){let t=document.createElementNS('http://www.w3.org/2000/svg',name);for(let [k,v] of Object.entries(attrs))t.setAttribute(k,v);svg.appendChild(t);return t}
 if(st.a===2){f.forEach((pair,i)=>{if(st.e[i]){const [u,v]=pair;elt('line',{x1:P[u][0],y1:P[u][1],x2:P[v][0],y2:P[v][1],stroke:'#25465b','stroke-width':6,'stroke-linecap':'round'})}})}
 else {f.forEach((h,i)=>{if(st.e[i])elt('polygon',{points:h.map(x=>P[x].join(',')).join(' '),fill:'#0d766e','fill-opacity':.17,stroke:'#0d766e','stroke-width':2})})}
 st.s.forEach((bit,i)=>{let [x,y]=P[i];let circ=elt('circle',{cx:x,cy:y,r:23,fill:bit?'#e2a339':'#0d766e',stroke:'white','stroke-width':4});circ.style.cursor='pointer';circ.addEventListener('click',()=>{st.s[i]^=1;history=history.slice(0,index+1);show()});let tx=elt('text',{x,y:y+5,'text-anchor':'middle','font-size':16,'font-weight':700,fill:'white'});tx.textContent=i+1;});
 const cols=document.getElementById('colors');cols.innerHTML='';st.s.forEach((v,i)=>{let l=document.createElement('label');l.innerHTML=`<input type="checkbox" ${v?'checked':''}> Spin ${i+1}`;l.querySelector('input').onchange=(ev)=>{st.s[i]=ev.target.checked?1:0;history=history.slice(0,index+1);show()};cols.appendChild(l)});
 const ee=document.getElementById('edges');ee.innerHTML='';f.forEach((h,i)=>{let l=document.createElement('label');l.innerHTML=`<input type="checkbox" ${st.e[i]?'checked':''}> ${h.map(x=>x+1).join('–')}`;l.querySelector('input').onchange=ev=>{st.e[i]=ev.target.checked?1:0;history=history.slice(0,index+1);show()};ee.appendChild(l)});
 const list=document.getElementById('history');list.innerHTML=history.map((h,i)=>`<div class="histrow" style="${i===index?'font-weight:700;color:#0a7068':''}"><span>t=${i}: ${h.e.reduce((a,b)=>a+b,0)} edges, ${h.s.reduce((a,b)=>a+b,0)} active spins</span><span>|Aut|=${autos(h,false)}</span></div>`).join('');document.getElementById('prev').disabled=index<=0;}
function load(st){history=[structuredClone(st)];index=0;show()}
function next(){if(index===history.length-1)history.push(step(history[index]));index++;show()}
function back(){if(index>0)index--;show()}
document.getElementById('next').onclick=next;document.getElementById('prev').onclick=back;
document.getElementById('model').onchange=e=>{document.getElementById('complement').checked=false;load(initial(+e.target.value))};document.getElementById('complement').onchange=()=>load(history[0]);document.getElementById('sample').onclick=()=>load(initial(+document.getElementById('model').value));document.getElementById('reset').onclick=()=>load(initial(+document.getElementById('model').value));
document.getElementById('play').onclick=()=>{if(timer)return;timer=setInterval(next,1000)};document.getElementById('stop').onclick=()=>{clearInterval(timer);timer=null};
const ce=[[0,1],[1,2],[2,3],[0,3]];document.getElementById('cycle').onclick=()=>{document.getElementById('model').value=2;load({a:2,e:PAIRS.map(p=>+ce.some(h=>eq(p,h))),s:[0,0,0,0]})};ce.forEach((h,i)=>{document.getElementById('delete'+i).onclick=()=>{document.getElementById('cycle').click();const v=history[0],k=PAIRS.findIndex(p=>eq(p,h));v.e[k]=0;show()}});
load(initial(2));
</script></body></html>'''
# browser self-contained motif JSON
jsmotifs=[{'colors':x['colors'],'e':x['edges']} for x in selected]
html=html.replace('__MOTIFS__',json.dumps(jsmotifs,separators=(',',':')))
from reference import TYPES
q2=[[j,{'colors':list(v[0]),'e':list(v[1])}] for j,v in TYPES[2][2]]
html=html.replace('__Q2CATALOG__',json.dumps(q2,separators=(',',':')))
(base/'WebDemo'/'index.html').write_text(html,encoding='utf-8')
